export type DataTableSort = DataViewSort;
export type DataTableColumnPinning = DataViewColumnPinning;

export type DataTableColumn<TData extends object> = {
  id: string;
  header: ReactNode;
  accessor?: keyof TData | ((row: TData) => unknown);
